//! JSON Schema export for every wire contract (spec §24.2). These files are the *interface* the
//! Python CLI (and any future SDK) is validated against: generated from the Rust types, checked in
//! under `schemas/`, and re-generated by CI so drift is a build failure, not a runtime surprise.

use std::path::{Path, PathBuf};

use schemars::{JsonSchema, schema_for};

use crate::{
    admission::PolicyDoc,
    config::HostConfig,
    error::Result,
    filesystem::ImageManifest,
    protocol::{RequestEnvelope, ResponseEnvelope},
    snapshot::SnapshotManifest,
};

fn write<T: JsonSchema>(dir: &Path, name: &str) -> Result<PathBuf> {
    let p = dir.join(name);
    let mut text = serde_json::to_string_pretty(&schema_for!(T))?;
    text.push('\n');
    std::fs::write(&p, text)?;
    Ok(p)
}

pub fn write_all(dir: &Path) -> Result<Vec<PathBuf>> {
    std::fs::create_dir_all(dir)?;
    Ok(vec![
        write::<RequestEnvelope>(dir, "request.schema.json")?,
        write::<ResponseEnvelope>(dir, "response.schema.json")?,
        write::<PolicyDoc>(dir, "policy.schema.json")?,
        write::<HostConfig>(dir, "host-config.schema.json")?,
        write::<SnapshotManifest>(dir, "snapshot-manifest.schema.json")?,
        write::<ImageManifest>(dir, "image-manifest.schema.json")?,
    ])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_contract_schema_is_generated_and_is_valid_json() {
        let d = tempfile::tempdir().unwrap();
        let files = write_all(d.path()).unwrap();
        assert_eq!(files.len(), 6);
        for f in files {
            let v: serde_json::Value = serde_json::from_slice(&std::fs::read(&f).unwrap()).unwrap();
            assert!(v.get("$schema").is_some() || v.get("title").is_some(), "{}", f.display());
        }
    }

    #[test]
    fn request_schema_pins_the_strictness_the_python_client_relies_on() {
        let v = serde_json::to_value(schema_for!(RequestEnvelope)).unwrap();
        assert_eq!(v["additionalProperties"], serde_json::json!(false), "unknown request fields must be rejected");
        let text = v.to_string();
        assert!(text.contains("sandbox_destroy") && text.contains("expected_generation"));
    }
}
